(() => {
  const layout=OfficeLayout,engine=new OfficeEngine(layout),T=layout.tile,W=layout.width*T,H=layout.height*T;
  state.officeTasks ||= [];state.officeChat ||= {};const taskKinds=['planning','research','analysis','coding','review'];
  const locations={planning:['manager','whiteboard','projectboard'],research:['research','bookshelf','research-terminal','documents'],analysis:['analysis','data-board'],coding:['developer','pair','ai'],review:['qa','qa-board','projectboard']};
  const labels={work:'Working',discuss:'Discussing',plan:'Planning',present:'Presenting',read:'Reading',research:'Researching',review:'Reviewing',analyse:'Analysing',print:'Printing',get_coffee:'Getting coffee',get_water:'Getting water',inspect:'Inspecting',organise:'Organising',sit:'Taking a break',take_break:'Taking a break',look_outside:'Looking outside',pet_cat:'Petting the cat',water_plant:'Tending a plant'};
  let chosen=0,hovered=null,canvas,ctx,background,raf=0,last=performance.now(),lastPanel=0,panelHTML='',paused=matchMedia('(prefers-reduced-motion: reduce)').matches,roam=true,zoom=1,message='Select a teammate, then click a location or open floor.',saveTimer;
  const actors=state.agents.map((_,i)=>{const saved=state.officePositionsV4?.[i],fallback=layout.spawns[i%layout.spawns.length],p=saved&&engine.walkable(saved.x,saved.y)?saved:fallback;return {x:p.x*T+8,y:p.y*T+12,path:[],direction:'down',clock:0,location:'Office floor',objectId:null,mode:'Idle',taskId:null,reason:null,holdUntil:0,nextAmbient:performance.now()+3500+i*1700}});
  function tile(a){return {x:Math.floor(a.x/T),y:Math.floor(a.y/T)}}
  function savePositions(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{state.officePositionsV4=actors.map(tile);persist()},400)}
  function say(text){message=text;const el=$('#office-message');if(el)el.textContent=text}
  function taskFor(i){const p=state.projects.find(p=>p.status==='Running'&&p.tasks[p.step]?.agent===i);if(p)return {id:p.id+':'+p.step,title:p.tasks[p.step].title,kind:taskKinds[i%5],project:p};const direct=state.officeTasks.find(t=>t.agent===i&&['Queued','Running'].includes(t.status));return direct?{...direct,direct}:null}
  function clearInteraction(i){engine.release(i);const a=actors[i];a.objectId=null;a.reason=null;a.holdUntil=0}
  function goLocation(i,ids,reason='manual',now=performance.now()){
    const a=actors[i];if(reason!=='task'&&taskFor(i)){say(`${state.agents[i].name} has an assigned task. Task activity takes priority.`);return false}
    const found=engine.choose(i,ids,tile(a));if(!found){if(reason==='task'){a.mode='Waiting for a free station';a.path=[]}else say('Those locations are occupied or unreachable. Try another location.');return false}
    a.path=found.route;a.objectId=found.object.id;a.reason=reason;a.mode=a.path.length?'Walking':labels[found.object.actions?.[0]]||'Using location';a.location=a.path.length?'On the way to '+found.object.name:found.object.name;a.holdUntil=now+9000+Math.random()*4000;
    if(!a.path.length)arrive(i,now);if(reason==='manual')say(`${state.agents[i].name} → ${found.object.name}${found.object.id!==ids[0]?' (alternative free location)':''}.`);updatePanel();return true;
  }
  function move(i,p){if(taskFor(i)){say('An assigned task takes priority. Choose an idle teammate to move manually.');return}const a=actors[i],route=engine.route(tile(a),p);if(route===null){say('Choose an open floor tile. Furniture and walls block walking.');return}clearInteraction(i);a.path=route;a.mode=route.length?'Walking':'Idle';a.location='Office floor';a.nextAmbient=performance.now()+14000;say(`${state.agents[i].name} is ${route.length?'walking there':'already there'}.`)}
  function arrive(i,now){const a=actors[i];if(a.objectId){const o=engine.objects.get(a.objectId);a.location=o.name;a.mode=labels[o.actions?.[0]]||'Using location';a.holdUntil=now+8000;if(a.reason==='task')a.mode='Working';}else a.mode='Idle';a.nextAmbient=now+6000+Math.random()*7000;savePositions();if(i===chosen)say(`${state.agents[i].name} arrived at ${a.location.toLowerCase()}.`)}
  function update(dt,now){actors.forEach((a,i)=>{
    const task=taskFor(i);
    if((task?.id||null)!==a.taskId){clearInteraction(i);a.taskId=task?.id||null;a.path=[];a.mode='Idle';if(task){goLocation(i,locations[task.kind]||locations[taskKinds[i%5]],'task',now);if(task.direct){task.direct.status='Running';persist()}}else a.nextAmbient=now+4000}
    if(task&&!a.objectId&&now>a.nextAmbient){goLocation(i,locations[task.kind]||locations.planning,'task',now);a.nextAmbient=now+1500}
    if(!paused){a.clock+=dt;if(a.path.length){const p=a.path[0],x=p.x*T+8,y=p.y*T+12,dx=x-a.x,dy=y-a.y,d=Math.hypot(dx,dy),step=dt*.055;a.direction=Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up';if(d<=step){a.x=x;a.y=y;a.path.shift();if(!a.path.length)arrive(i,now)}else{a.x+=dx/d*step;a.y+=dy/d*step}}
      else if(!task&&a.objectId&&now>a.holdUntil){clearInteraction(i);a.mode='Idle';a.nextAmbient=now+2500}
      else if(!task&&roam&&!a.path.length&&!a.objectId&&now>a.nextAmbient){const candidates=engine.interactions.filter(o=>['break','fun','research'].includes(o.kind)).map(o=>o.id);const start=Math.floor(Math.random()*candidates.length);goLocation(i,[...candidates.slice(start),...candidates.slice(0,start)],'ambient',now);a.nextAmbient=now+9000}
    }
    if(task?.direct&&!a.path.length&&a.objectId){task.direct.remainingMs=Math.max(0,task.direct.remainingMs-dt);if(task.direct.remainingMs===0){task.direct.status='Completed';task.direct.output='Simulated task completed. No AI provider or tool was called.';log(`${state.agents[i].name} completed demo task “${task.title}”.`);persist();a.taskId=null;clearInteraction(i);a.mode='Idle';a.nextAmbient=now+6000;say(`${state.agents[i].name} completed the demo task.`)}}
  })}
  function makeBackground(){const c=document.createElement('canvas');c.width=W;c.height=H;const g=c.getContext('2d');g.imageSmoothingEnabled=false;for(let y=0;y<layout.height;y++)for(let x=0;x<layout.width;x++)g.drawImage(PixelAssets.asset('floor'),x*T,y*T);
    for(const z of layout.zones){g.fillStyle=z.color;g.fillRect(z.x*T,z.y*T,z.w*T,z.h*T);g.fillStyle='#805038';g.fillRect(z.x*T,z.y*T,z.w*T,1);g.fillRect(z.x*T,(z.y+z.h)*T-1,z.w*T,1);for(let y=z.y*T+7;y<(z.y+z.h)*T;y+=8){g.fillStyle='#805038';g.fillRect(z.x*T,y,z.w*T,1)}}
    for(let x=0;x<layout.width;x++)g.drawImage(PixelAssets.asset('wall'),x*T,0);g.fillStyle='#192432';g.fillRect(0,32,T,H-32);g.fillRect(W-T,32,T,H-32);g.fillRect(0,H-T,W,T);g.fillStyle='#805038';g.fillRect(T,32,1,H-48);g.fillRect(W-T-1,32,1,H-48);g.fillStyle='#b87945';g.fillRect(W/2-16,H-T,32,T);background=c;
  }
  function drawObject(o){const asset=PixelAssets.asset(o.asset);ctx.drawImage(asset,Math.round(o.x*T+(o.offsetX||0)),Math.round(o.y*T+(o.offsetY||0)));if(hovered?.object===o.id){ctx.fillStyle='#e5c77b';ctx.fillRect(o.x*T,o.y*T,o.width*T,1);ctx.fillRect(o.x*T,(o.y+o.height)*T-1,o.width*T,1)}}
  function actionFor(a){if(a.path.length&&!paused)return 'walk';if(/coffee/i.test(a.mode))return 'coffee';if(/Reading|Research/i.test(a.mode))return 'reading';if(a.mode==='Working')return 'working';return 'idle'}
  function drawAgent(a,i){const x=Math.round(a.x)-8,y=Math.round(a.y);if(i===chosen){ctx.fillStyle='#e5c77b';ctx.fillRect(x-1,y+1,18,1);ctx.fillRect(x-1,y-1,1,2);ctx.fillRect(x+16,y-1,1,2)}AgentSkins.draw(ctx,i,actionFor(a),a.direction,Math.floor(a.clock/150)%4,x,y);if(taskFor(i)){ctx.fillStyle='#78b997';ctx.fillRect(x+6,y-28,3,3)}}
  function draw(now){if(!canvas?.isConnected){raf=0;return}const dt=Math.min(now-last,50);last=now;update(dt,now);ctx.clearRect(0,0,W,H);ctx.drawImage(background,0,0);const things=[...layout.objects.map(o=>({z:(o.y+o.height)*T,draw:()=>drawObject(o)})),...actors.map((a,i)=>({z:a.y,draw:()=>drawAgent(a,i)}))];things.sort((a,b)=>a.z-b.z).forEach(item=>item.draw());const dest=actors[chosen].path.at(-1);if(dest){ctx.fillStyle='#e5c77b';const x=dest.x*T+6,y=dest.y*T+10;ctx.fillRect(x,y,5,1);ctx.fillRect(x+2,y-2,1,5)}if(now-lastPanel>500){updatePanel();lastPanel=now}raf=requestAnimationFrame(draw)}
  function point(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)/zoom,y:(e.clientY-r.top)/zoom}}
  function pick(p){const agent=actors.map((a,i)=>({a,i})).reverse().find(({a})=>Math.abs(a.x-p.x)<10&&p.y>=a.y-28&&p.y<=a.y+3);if(agent)return {agent:agent.i};const object=[...engine.interactions].reverse().find(o=>p.x>=o.x*T&&p.x<(o.x+o.width)*T&&p.y>=o.y*T&&p.y<(o.y+o.height)*T);return object?{object:object.id}:null}
  function selected(i){chosen=i;hovered=null;document.querySelectorAll('[data-office-agent]').forEach(b=>{const on=Number(b.dataset.officeAgent)===i;b.setAttribute('aria-pressed',on);b.classList.toggle('selected',on)});say(`Selected ${state.agents[i].name}. ${taskFor(i)?'Assigned task takes priority.':'Click a location or open floor to move.'}`);updatePanel(true)}
  function updatePanel(force=false){const el=$('#employee-context');if(!el)return;const a=actors[chosen],agent=state.agents[chosen],task=taskFor(chosen),recent=state.events.filter(e=>e.text.includes(agent.name)).slice(0,2);const html=`<div class="portrait-line"><canvas id="employee-portrait" width="64" height="96" aria-label="${esc(agent.name)} pixel portrait"></canvas><div><h2>${esc(agent.name)}</h2><div class="small muted">${esc(agent.role)}</div>${badge(a.mode,task?'demo':'')}</div></div><dl class="context-details"><dt>Current task</dt><dd>${task?esc(task.title):'No assigned task'}</dd><dt>Location</dt><dd>${esc(a.location)}</dd><dt>Model</dt><dd>${esc(agent.provider)} · not connected</dd><dt>Tokens / cost</dt><dd>0 tokens · $0.00</dd></dl><div class="context-actions"><button data-office="desk">Go to desk</button><button data-office="move">Move</button><button class="primary" data-office="assign">Assign task</button><button data-office="chat">Chat</button><button data-office="details">Employee details</button><button data-office="appearance">Appearance</button></div><details class="recent-context"><summary>Recent activity</summary>${recent.map(e=>`<p class="small muted">${esc(e.text)}</p>`).join('')||'<p class="small muted">No recorded activity yet.</p>'}</details>`;if(force||html!==panelHTML){panelHTML=html;el.innerHTML=html;const c=$('#employee-portrait').getContext('2d');c.imageSmoothingEnabled=false;AgentSkins.draw(c,chosen,'idle','down',0,0,96,4)}}
  function mount(){canvas=$('#office-canvas');ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;canvas.style.width=W*zoom+'px';canvas.style.height=H*zoom+'px';canvas.addEventListener('pointerdown',e=>{canvas.focus();const p=point(e),hit=pick(p);if(hit?.agent!==undefined)selected(hit.agent);else if(paused)say('Resume motion to send a teammate somewhere.');else if(hit?.object){const o=engine.objects.get(hit.object),alternatives=engine.interactions.filter(x=>x.kind===o.kind&&x.id!==o.id).map(x=>x.id);goLocation(chosen,[o.id,...alternatives])}else move(chosen,{x:Math.floor(p.x/T),y:Math.floor(p.y/T)})});
    canvas.addEventListener('pointermove',e=>{const p=point(e);hovered=pick(p);const tip=$('#office-tooltip');if(!hovered){tip.hidden=true;return}tip.textContent=hovered.agent!==undefined?state.agents[hovered.agent].name:(()=>{const o=engine.objects.get(hovered.object);return `${o.name} · ${engine.occupancy(o.id)}/${o.capacity} in use`})();tip.hidden=false;tip.style.left=Math.min(e.offsetX+12,canvas.clientWidth-170)+'px';tip.style.top=Math.max(0,e.offsetY-32)+'px'});canvas.addEventListener('pointerleave',()=>{hovered=null;$('#office-tooltip').hidden=true});
    canvas.addEventListener('keydown',e=>{const dirs={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]};if(dirs[e.key]){e.preventDefault();if(paused)return;const a=actors[chosen],p=a.path.at(-1)||tile(a),[dx,dy]=dirs[e.key];move(chosen,{x:p.x+dx,y:p.y+dy})}if(e.key==='Enter')employee(chosen)});updatePanel(true);if(!raf){last=performance.now();raf=requestAnimationFrame(draw)}}
  function assign(){show(`<h2>Assign a task to ${esc(state.agents[chosen].name)}</h2><p class="notice">This is a local simulation. No AI provider or execution tool is connected.</p><form id="office-task-form"><label for="office-task-title">Task</label><input id="office-task-title" name="title" required maxlength="120" placeholder="e.g. Review the prototype"><label for="office-task-kind">Activity</label><select name="kind" id="office-task-kind">${taskKinds.map(k=>`<option value="${k}" ${taskKinds[chosen%5]===k?'selected':''}>${k[0].toUpperCase()+k.slice(1)}</option>`).join('')}</select><div class="dialog-actions"><button type="button" data-close>Cancel</button><button class="primary">Assign demo task</button></div></form>`);$('#office-task-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim();if(!title)return;state.officeTasks.push({id:crypto.randomUUID(),agent:chosen,title,kind:f.get('kind'),status:'Queued',remainingMs:14000});log(`Assigned demo task “${title}” to ${state.agents[chosen].name}.`);persist();$('#dialog').close();updatePanel(true)}}
  function chat(){const k=state.agents[chosen].id||`employee-${chosen}`;state.officeChat[k] ||= [];show(`<h2>Chat · ${esc(state.agents[chosen].name)}</h2><p class="notice">Local demo chat. Messages stay in the app; replies are scripted, not AI-generated.</p><div id="office-chat-messages">${state.officeChat[k].slice(-8).map(m=>`<p><strong>${esc(m.who)}:</strong> ${esc(m.text)}</p>`).join('')||'<p class="muted">Leave a message for this teammate.</p>'}</div><form id="office-chat-form"><label for="office-chat-text">Message</label><input id="office-chat-text" required maxlength="500"><div class="dialog-actions"><button type="button" data-close>Close</button><button class="primary">Send locally</button></div></form>`);$('#office-chat-form').onsubmit=e=>{e.preventDefault();const text=$('#office-chat-text').value.trim();if(!text)return;state.officeChat[k].push({who:'You',text},{who:state.agents[chosen].name,text:'Message saved locally. Use Assign task to try my office workflow; a model connection is needed for real AI responses.'});state.officeChat[k]=state.officeChat[k].slice(-40);persist();chat()}}
  const baseBody=bodyView;bodyView=function(p){let html=baseBody(p);if(view==='Tasks'&&state.officeTasks.length)html=`<section class="panel office-task-list"><div class="panel-head"><h2>Direct employee tasks · demo</h2></div>${state.officeTasks.slice().reverse().map(t=>`<div class="task"><div class="task-main"><h3>${esc(t.title)}</h3><p class="muted">${esc(state.agents[t.agent]?.name)} · ${esc(t.kind)}</p></div>${badge(t.status)}${t.status==='Completed'?'<span class="small muted">Simulated result</span>':''}</div>`).join('')}</section>`+html;return html};
  const baseRender=render;render=function(){baseRender();document.title='Ruang — Pixel Office';const brand=$('.brand');if(brand)brand.innerHTML='<span class="ruang-mark">R</span> RUANG';if($('.tagline'))$('.tagline').textContent='Idea besar. Ruang sendiri.';if(view!=='Office')return;
    const p=project();$('.main').innerHTML=`<header class="topbar"><div><div class="eyebrow">RUANG / YOUR LOCAL AI WORKSPACE</div><h1>Your office, in motion.</h1><p class="welcome-sub">Small team. Shared space. Big ideas.</p></div><div class="top-actions">${badge(window.desktop?'Desktop · AI demo':'AI demo','demo')}<button class="primary" data-action="new-project">＋ New project</button></div></header><div class="compact-office-layout"><section class="panel office-simulation"><div class="room-toolbar"><div><strong>Our office</strong><span class="small muted">${state.agents.length} teammates</span></div><div><button data-office="pause">${paused?'▶ Resume':'Ⅱ Pause'}</button><button data-office="roam" aria-pressed="${roam}">Wander ${roam?'on':'off'}</button><button data-office="zoom" aria-label="Change office zoom">${zoom}× zoom</button></div></div><div class="office-viewport"><div class="office-pixel-stage" style="width:${W*zoom}px;height:${H*zoom}px"><canvas id="office-canvas" width="${W}" height="${H}" tabindex="0" role="application" aria-label="Pixel office. Select an employee below, then click an object or floor to move. Arrow keys walk; Enter opens details."></canvas><div id="office-tooltip" hidden></div></div></div><div class="room-hint"><span id="office-message" role="status">${esc(message)}</span><span class="keyboard-hint">Click to interact · arrows to walk</span></div><div class="character-picker">${state.agents.map((a,i)=>`<button class="character-choice ${i===chosen?'selected':''}" data-office-agent="${i}" aria-pressed="${i===chosen}"><span class="character-dot" style="background:${['#d5ae56','#87a353','#7797a2','#a6afa4','#e3d5b1'][i%5]}"></span><span><b>${esc(a.name)}</b><small>${esc(a.role)}</small></span></button>`).join('')}</div><div class="location-controls"><label for="office-location">Send selected teammate to</label><select id="office-location">${engine.interactions.map(o=>`<option value="${o.id}">${esc(o.name)} · capacity ${o.capacity}</option>`).join('')}</select><button data-office="location">Go</button></div></section><aside class="room-sidebar"><section class="panel pad" id="employee-context"></section><section class="panel pad"><div class="row"><h2>Project board</h2>${p?badge(p.status):''}</div>${p?projectSummary(p):'<p class="muted small">Try a project to watch the team at work.</p><button class="primary" data-action="demo">Try a demo project</button>'}</section><p class="small muted room-note">Office actions and AI tasks are simulated. Local file editing under Files is real.</p></aside></div><section class="panel activity"><div class="panel-head"><h2>Recent activity</h2><button class="quiet small" data-view="Activity">View all</button></div>${eventsHTML(3)}</section>`;mount()};
  document.addEventListener('click',e=>{const b=e.target.closest('[data-office],[data-office-agent]');if(!b)return;if(b.dataset.officeAgent!==undefined)selected(Number(b.dataset.officeAgent));const action=b.dataset.office;if(action==='pause'){paused=!paused;render()}if(action==='roam'){roam=!roam;if(!roam)actors.forEach((a,i)=>{if(a.reason==='ambient'){clearInteraction(i);a.path=[];a.mode='Idle'}});render()}if(action==='zoom'){zoom=zoom===1?2:1;render()}if(action==='desk')goLocation(chosen,[layout.homeByAgent[chosen%5]]);if(action==='move'){say(taskFor(chosen)?'Assigned tasks take priority over manual movement.':'Click an open floor tile to move the selected teammate.');canvas.focus()}if(action==='assign')assign();if(action==='chat')chat();if(action==='details')employee(chosen);if(action==='appearance')AgentSkins.appearance(chosen);if(action==='location'){const id=$('#office-location').value,o=engine.objects.get(id);goLocation(chosen,[id,...engine.interactions.filter(x=>x.kind===o.kind&&x.id!==id).map(x=>x.id)])}});
  makeBackground();render();
})();
